from flask import Flask, request

app = Flask(__name__)

def check_mod():
    # 从 URL 参数中获取用户名和密码
    username = request.args.get('username')
    password = request.args.get('password')

    # 检查用户名和密码是否正确
    if username == "admin" and password == "123456":
        return "true"
    else:
        return "false"

@app.route('/check_mod')
def check_mod_route():
    return check_mod()

if __name__ == '__main__':
    app.run(debug=True)

