from flask import Flask, request, jsonify

app = Flask(__name__)

# نمونہ صارف نام اور پاس ورڈ (آپ اسے ڈیٹا بیس سے بھی حاصل کر سکتے ہیں)
USERNAME = "admin"
PASSWORD = "password123"

@app.route('/چیک_موڈ', methods=['GET'])
def چیک_موڈ():
    # URL سے صارف نام اور پاس ورڈ حاصل کریں
    username = request.args.get('username')
    password = request.args.get('password')

    # چیک کریں کہ کیا صارف نام اور پاس ورڈ درست ہیں
    if username == USERNAME and password == PASSWORD:
        return jsonify({'result': 'سچ'})
    else:
        return jsonify({'result': 'غلط'})

if __name__ == '__main__':
    app.run(debug=True)

